const defaults={demoSeeded:true,points:120,rice:0,minutes:165,sessions:6,connections:['aya','riku','ken'],recentTogether:['aya','mio','riku','ken'],roomHistory:demoHistory,tasks:[{id:1,title:'レポートの下書きを仕上げる',date:todayISO,subject:'心理学概論',done:false,demo:true},{id:2,title:'英語の課題 Unit 3',date:todayISO,subject:'英語コミュニケーション',done:false,demo:true},{id:3,title:'ゼミの発表テーマを考える',date:todayISO,subject:'基礎ゼミ',done:false,demo:true},{id:4,title:'履修登録を確認する',date:todayISO,subject:'大学生活',done:true,demo:true}]};
