function collectRate(){const got=dishes.filter(([,r])=>state.rice>=r).length,pct=Math.round(got/dishes.length*100);return `<div class="collect-rate"><div class="between"><b>コレクション ${got} / ${dishes.length}</b><span>${pct}%</span></div><div class="progress collect-progress"><div style="width:${pct}%"></div></div></div>`}
function stage(){return state.points>=300?'収穫のとき':state.points>=200?'実りの時期':state.points>=100?'すくすく期':'田植えの時期'}
function farm(){const level=Math.min(6,Math.floor(state.points/60)+1);const rice='rice_stage_0'+level;const places=[[50,27],[44,32],[56,33],[25,46],[20,51],[31,52],[73,46],[68,51],[79,52],[49,65],[43,70],[55,71]];const sky=skyKind(),w=freshWeather();return `<div class="farmart supplied-field sky-${sky}" role="img" aria-label="${stage()}の田んぼ"><div class="field-land"></div>${w?`<span class="weather-chip">SFC ${weatherLabel(w.code)} ${w.temp}℃</span>`:''}${sky==='clear'&&(!w||w.code<=1)?art('sun','field-sun'):''}${art('mountain','field-mountain')}${art('hill','field-hill')}${art('university','field-university')}${art('tree','field-tree')}<div class="paddy-scene">${art('paddy_4_plots','field-paddy')}${places.map(([x,y])=>`<img class="field-rice" src="${suppliedAssets[rice]}" alt="" style="left:${x}%;top:${y}%">`).join('')}</div>${art('students_study_02','field-students')}${art('rice_mascot_normal','field-mascot')}${art('bush','field-bush')}${art('flower','field-flower')}</div>`}
function farmFriends(){const list=state.connections.map(k=>people[k]);if(!list.length)return `<button class="farm-friends empty" data-page="friends" aria-label="仲間をさがす">${art('students_group_02','farm-friends-art','')}<span>仲間と一緒に育てよう</span>${icon('right')}</button>`;return `<button class="farm-friends" data-friend-view="people" data-page="friends" aria-label="一緒に育てる仲間"><span class="farm-faces">${list.slice(0,3).map(p=>`<span class="avatar sprite s${p.avatar}"></span>`).join('')}</span><span class="farm-friends-text">${list.slice(0,2).map(p=>esc(p.name)).join('・')}${list.length>2?` ほか${list.length-2}人`:''}と育て中</span>${state.togetherPoints?`<span class="farm-together">+${state.togetherPoints}pt</span>`:''}${icon('right')}</button>`}
function head(title){return `<div class="heading"><div><h1>${title}</h1></div><span class="date">${today.toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'long'})}</span></div>`}
function taskRows(tasks,expanded=false){
 const complete=tasks.length&&tasks.every(t=>t.done);
 if(page==='home'&&complete&&!expanded)return `<div class="all-done">${art('task_complete','','')}<strong>今日のタスク完了！</strong></div><details class="completed-tasks"><summary>完了したタスクを見る</summary>${taskRows(tasks,true)}</details>`;
 if(state.settings.hideCompleted&&!expanded)tasks=tasks.filter(t=>!t.done);
 tasks=[...tasks].sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));
 const size=expanded?tasks.length:page==='home'?homeFit:taskFit;
 taskPage=Math.max(0,Math.min(taskPage,Math.ceil(tasks.length/size)-1));
 return tasks.length?tasks.slice(taskPage*size,(taskPage+1)*size).map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" aria-label="${esc(t.title)}を完了" data-task="${t.id}" ${t.done?'checked':''}><div><button class="task-title" data-edit-task="${t.id}" aria-label="${esc(t.title)}を編集"><strong>${esc(t.title)}</strong><span class="task-edit-hint">${icon('edit')}</span></button><small>${esc(t.subject)}${t.focusMinutes?` · 集中 ${t.focusMinutes}分`:''}</small></div><span class="tag ${!t.done&&t.date<=todayISO?'urgent':''}">${t.done?'完了':t.date<todayISO?'期限超過':t.date===todayISO?'今日まで':'予定'}</span>${page==='tasks'?`<button class="task-delete" data-delete-task="${t.id}" aria-label="${esc(t.title)}を削除" title="タスクを削除">${icon('trash')}</button>`:''}</div>`).join('')+(tasks.length>size?`<div class="pager"><button aria-label="前のタスク" data-task-next="-1" ${taskPage===0?'disabled':''}>‹</button><span>${taskPage+1} / ${Math.ceil(tasks.length/size)}</span><button aria-label="次のタスク" data-task-next="1" ${(taskPage+1)*size>=tasks.length?'disabled':''}>›</button></div>`:''):'<div class="empty">表示するタスクはありません。</div>';
}
function render(){if(typing()){pendingRender=true;return}if(!state.loggedIn){document.body.dataset.page='login';document.body.dataset.loginStep=loginStep;main.innerHTML=loginStep==='form'?loginView():welcomeView();return}if(page==='focus'){page='friends';friendView='rooms'}document.body.dataset.page=page;document.body.dataset.sky=skyKind(); $('#nav').innerHTML=menus.map(([p,l])=>`<button data-page="${p}" class="${(page===p||(p==='profile'&&page==='collection'))?'active':''}" aria-label="${l}" title="${l}" ${(page===p||(p==='profile'&&page==='collection'))?'aria-current="page"':''}>${navIcon(p)}</button>`).join('');if(page==='home'){main.innerHTML=head('みんなで育てよう')+`<div class="grid"><section class="card farm">${farm()}<div class="farmbottom"><div class="between"><b>${stage()}</b><span class="subtle">${state.points} / 300 pt</span></div><div class="progress"><div style="width:${Math.min(100,state.points/3)}%"></div></div>${state.points>=300?'<button class="primary" data-harvest style="margin-top:15px;width:100%">実りを収穫する</button>':''}</div></section>${quickFocus()}</div><div class="grid lowgrid"><section class="card"><div class="between"><h2 class="sectiontitle">今日のタスク <span class="taskcount">${homeTasks().filter(t=>t.done).length} / ${homeTasks().length}</span></h2><button class="textbtn icon-btn" data-add aria-label="タスクを追加" title="タスクを追加">${icon('plus')}</button></div>${taskRows(homeTasks())}</section></div>`}else if(page==='tasks'){main.innerHTML=head('今日のやること')+`<div class="grid"><section class="card"><div class="between"><button class="textbtn icon-btn" data-month="-1" aria-label="前月" title="前月">${icon('left')}</button><div class="month-heading"><h2 class="sectiontitle">${month.getFullYear()}年 ${month.getMonth()+1}月</h2></div><button class="textbtn icon-btn" data-month="1" aria-label="翌月" title="翌月">${icon('right')}</button></div><div class="calendar">${['月','火','水','木','金','土','日'].map(x=>`<div class="week">${x}</div>`).join('')}${calendar()}</div></section><section class="card"><div class="between"><h2 class="sectiontitle">${selectedDate.slice(5).replace('-','月')}日のタスク</h2><button class="textbtn icon-btn" data-add aria-label="タスクを追加" title="タスクを追加">${icon('plus')}</button></div>${dayRecordButton(selectedDate)}${taskRows(state.tasks.filter(t=>t.date===selectedDate))}</section></div>`}else if(page==='friends'){main.innerHTML=renderFriends();}else if(page==='collection'){main.innerHTML=head('実りをあつめよう <button class="textbtn icon-btn back-profile" data-page="profile" aria-label="マイページに戻る" title="戻る">'+icon('left')+'</button>')+`<section class="card"><div class="between"><div><h2 class="harvest-heading"><span>収穫したお米</span><span class="harvest-amount">${state.rice}<small>カップ</small></span></h2><p class="subtle">300 pt → お米3カップ</p></div><button class="primary" data-harvest ${state.points<300?'disabled':''}>${state.points>=300?'収穫する':'あと '+(300-state.points)+' pt'}</button></div><div class="progress"><div style="width:${Math.min(100,state.points/3)}%"></div></div>${collectRate()}<div class="collect">${dishes.map(([n,r])=>`<article>${state.rice<r?`<span class="food-lock" aria-label="未解放">${icon('lock')}</span>`:''}<div class="food-art sprite s${r===3?8:r===6?9:10} ${state.rice>=r?'':'locked'}" role="img" aria-label="${n}"></div><b>${n}</b><p>${state.rice>=r?'解放済み':r+'カップ<br>収穫で解放'}</p></article>`).join('')}</div></section>`}else{main.innerHTML=`<section class="card profile-card"><div class="profile-identity"><span class="avatar sprite s${state.profile.avatar}" role="img" aria-label="プロフィールアイコン"></span><div><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.university)} · ${esc(state.profile.year)}</p>${state.profile.department?`<p>${esc(state.profile.department)}</p>`:''}</div><button class="textbtn icon-btn" id="editProfile" aria-label="プロフィールを編集" title="プロフィールを編集">${icon('edit')}</button></div><p class="stats-label">累計</p><div class="stats"><div><strong>${state.minutes}<small>分</small></strong><span>集中時間</span></div><div><strong>${state.completedTaskIds.length}</strong><span>完了したタスク</span></div><div><strong>${new Set(state.roomHistory.flatMap(h=>h.with)).size}<small>人</small></strong><span>いっしょに集中</span></div></div><button class="profile-collection" data-page="collection">${art('rice_bundle','collection-entry-art','')}<span><b>収穫・図鑑</b><small>お米 ${state.rice} カップ · 図鑑 ${dishes.filter(([,r])=>state.rice>=r).length} / ${dishes.length}</small></span>${icon('right')}</button><button class="profile-settings" id="openGuide">${icon('help')}<span>使い方</span>${icon('right')}</button><button class="profile-settings" id="openSettings">${icon('settings')}<span>設定</span>${icon('right')}</button></section>`}fitTasks();if(page==='friends'&&friendView==='people')layoutMap()}
// 画面に収まらない分は次のページへ送る（スクロールなしのレイアウトでページ送りが隠れないように）
function fitTasks(){if(page==='home'){const f=$('.farm');if(f&&homeFit>1&&(f.getBoundingClientRect().height<innerHeight*.47||main.scrollHeight>main.clientHeight+1)){homeFit--;render()}return}main.classList.remove('fit-scroll');if(page!=='tasks'||getComputedStyle(main).overflowY!=='hidden')return;if(main.scrollHeight>main.clientHeight+1){if(taskFit>1){taskFit--;render()}else main.classList.add('fit-scroll')}}
// 文字を打っている最中は描き直さない（スマホでキーボードが開くと高さが変わって resize が起きるため）
// 文字を打っている最中かどうか（チェックボックスやファイル選択は除く）。打っている間は描き直しを後回しにする
const typing=()=>{const el=document.activeElement;return !!el&&!!el.closest?.('#main')&&el.matches('input:not([type=checkbox]):not([type=radio]):not([type=file]),textarea')};
let pendingRender=false;
main.addEventListener('focusout',()=>{setTimeout(()=>{if(pendingRender&&!typing()){pendingRender=false;render()}},50)});
let lastWidth=innerWidth;
window.addEventListener?.('resize',()=>{clearTimeout(window.fitTimer);window.fitTimer=setTimeout(()=>{if(typing()&&innerWidth===lastWidth)return;lastWidth=innerWidth;taskFit=5;homeFit=4;render()},150)});

function calendar(){let h='',offset=(month.getDay()+6)%7;for(let i=0;i<offset;i++)h+='<div></div>';for(let d=1;d<=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();d++){let dt=iso(new Date(month.getFullYear(),month.getMonth(),d)),n=state.tasks.filter(t=>t.date===dt).length;const rec=dayRecord(dt);h+=`<button class="day ${selectedDate===dt?'chosen':''} ${dt===todayISO?'is-today':''} ${rec.any?'has-record':''}" aria-label="${dt}${dt===todayISO?' 今日':''}${n?' タスク'+n+'件':''}${rec.any?' がんばりの記録あり':''}" aria-pressed="${selectedDate===dt}" data-date="${dt}">${d}${n?'<i class="day-dot" aria-hidden="true"></i>':''}</button>`}return h}
function timeText(){return `${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`}
function modal(content){stopCamera();$('#modalcontent').innerHTML=content;if(!$('#modal').open)$('#modal').showModal()}
function openAdd(id){refreshDay();const existing=state.tasks.find(t=>t.id===id),t=existing||{title:'',subject:'',date:page==='tasks'?selectedDate:todayISO};modal(`<h2>${existing?'タスクを編集':'タスクを追加'}</h2><form id="addform"><label>やること<input name="title" required maxlength="80" value="${esc(t.title)}" placeholder="例：英語のレポートを書く"></label><label>授業・カテゴリー<input name="subject" maxlength="40" value="${esc(t.subject)}"></label><label>締切<input name="date" type="date" required value="${esc(t.date)}"></label><p id="taskError" role="alert"></p><button class="primary icon-btn" aria-label="タスクを保存">${icon('check')}</button></form>`);$('#addform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),date=f.get('date');if(!title||!/^\d{4}-\d{2}-\d{2}$/.test(date)){$('#taskError').textContent='やることと締切を入力してください。';return}const values={title,subject:f.get('subject').trim()||'自分の目標',date};if(existing){Object.assign(existing,values);delete existing.demo}else state.tasks.push({id:Date.now(),...values,done:false});if(page==='tasks'){selectedDate=date;month=new Date(date+'T12:00:00');month.setDate(1);taskPage=0}save();$('#modal').close();render();toast(existing?'タスクを更新しました':'新しい目標を植えました',existing?'':'rice_stage_02')}}
document.addEventListener('click',e=>{const card=e.target.closest('[data-go-rooms]');if(card&&!e.target.closest('button')){page='friends';friendView='rooms';taskPage=0;render();return}const b=e.target.closest('button,a');if(!b)return;if(b.id==='retrySave'){if(save())toast('保存しました');return}if(b.id==='dismissSaveError'){$('#toast').classList.remove('show');return}refreshDay();if(b.hasAttribute('data-task-next')){taskPage+=Number(b.dataset.taskNext);render()}if(b.dataset.page){taskPage=0;taskFit=5;homeFit=4;page=b.dataset.page;render();window.scrollTo(0,0)}if(b.dataset.friendView){friendView=b.dataset.friendView;render()}if(b.dataset.mapPerson){mapSelected=b.dataset.mapPerson;if(b.hasAttribute('data-close-modal'))$('#modal').close();render()}if(b.dataset.mapHistory)openTogetherHistory(b.dataset.mapHistory);if(b.hasAttribute('data-map-more'))openMapList();if(b.dataset.person)openPerson(b.dataset.person);if(b.dataset.connect){const key=b.dataset.connect;if(!people[key])return;const added=!state.connections.includes(key);state.connections=added?[...state.connections,key]:state.connections.filter(x=>x!==key);save();render();openPerson(key);toast(added?people[key].name+'さんを仲間に追加しました':'仲間から外しました')}if(b.dataset.editTask)openAdd(Number(b.dataset.editTask));if(b.dataset.deleteTask)openDeleteTask(Number(b.dataset.deleteTask));if(b.dataset.confirmDeleteTask)deleteTask(Number(b.dataset.confirmDeleteTask));if(b.id==='editProfile')openProfileEditor();if(b.id==='openSettings')openSettings();if(b.id==='openGuide')openGuide();if(b.hasAttribute('data-start')){enterApp();return}if(b.hasAttribute('data-login-form')){loginStep='form';render();return}if(b.hasAttribute('data-login-back')){loginStep='welcome';render();return}if(b.dataset.dayRecord)openDayRecord(b.dataset.dayRecord);if(b.dataset.cameraSession!==undefined||b.dataset.cameraDay)openCamera({session:b.dataset.cameraSession?Number(b.dataset.cameraSession):null,task:b.dataset.cameraTask||'',date:b.dataset.cameraDay||''});if(b.id==='camShutter')takeShot();if(b.id==='camFlip')flipCamera();if(b.id==='camRetake')openCamera(cam.opts);if(b.id==='camSave')saveShot();if(b.dataset.photoView)openPhoto(b.dataset.photoView);if(b.dataset.photoDelete)deletePhoto(b.dataset.photoDelete);if(b.hasAttribute('data-logout')){state.loggedIn=false;loginStep='welcome';if(running)leaveRoom();save();$('#modal').close();page='home';render();return}if(b.hasAttribute('data-add'))openAdd();if(b.dataset.month){month.setMonth(month.getMonth()+Number(b.dataset.month));render()}if(b.dataset.date){selectedDate=b.dataset.date;taskPage=0;taskFit=5;render()}if(b.dataset.roomDuration&&!running){customTime=false;setDuration(Number(b.dataset.roomDuration));render()}if(b.hasAttribute('data-room-custom')){customTime=true;render();$('#roomMinutes')?.focus();$('#roomMinutes')?.select()}if(b.hasAttribute('data-arrived')&&state.room&&!state.room.arrived){state.room.arrived=true;save();render();toast(people[state.room.host].name+'さんに着いたことを知らせました','rice_mascot_happy')}if(b.hasAttribute('data-open-room'))openOwnRoom();if(b.dataset.room)openRoom(b.dataset.room);if(b.dataset.joinRoom)joinRoom(b.dataset.joinRoom);if(b.hasAttribute('data-leave-room'))modal(`<h2>作業場を出ますか？</h2><p>${focusedMinutes()>=1?`ここまでの${focusedMinutes()}分は、半分の +${focusedMinutes()} pt になります。`:'まだ1分たっていないので、ポイントはつきません。'}</p><div class="delete-actions"><button class="textbtn closemodal">やめる</button><button class="delete-confirm" data-confirm-leave>出る</button></div>`);if(b.hasAttribute('data-confirm-leave'))leaveRoom();if(b.dataset.stamp&&state.room){const names=roomMembers(state.room).map(o=>people[o[0]].name);toast(`${names.join('・')}さんに「${b.dataset.stamp}」を送りました`,'rice_mascot_happy');if(!state.room.replied){state.room.replied=true;save();const k=roomMembers(state.room)[0][0];setTimeout(()=>{if(state.room)toast(`${people[k].name}さんから「${b.dataset.stamp==='おつかれ'?'おつかれ':'がんばろう'}」`,'rice_mascot_happy')},2600)}}if(b.dataset.cheer&&people[b.dataset.cheer])toast(people[b.dataset.cheer].name+'さんに拍手を送りました','rice_mascot_happy');if(b.dataset.befriend){const key=b.dataset.befriend;if(people[key]&&!state.connections.includes(key)){state.connections=[...state.connections,key];save();render();b.classList.add('done');b.disabled=true;b.setAttribute('aria-label',people[key].name+'さんと仲間になりました');b.querySelector('.befriend-badge').innerHTML=icon('check');toast(people[key].name+'さんと仲間になりました','rice_mascot_happy')}return}if(b.dataset.completeTask){const t=state.tasks.find(t=>t.id===Number(b.dataset.completeTask));if(t)completeTask(t,true);$('#modal').close();page='home';render()}if(b.hasAttribute('data-harvest')&&state.points>=300){state.points-=300;state.rice+=3;save();render();modal('<h2>収穫できました！</h2><img class="result-art asset-img" src="assets/library/effect_harvest_success.webp" alt="収穫成功"><p>お米 +3カップ</p><button class="primary closemodal" data-page="collection">図鑑で料理を見る</button><button class="textbtn closemodal">また育てよう</button>')}if(b.matches('.close,.closemodal'))$('#modal').close();});
document.addEventListener('change',e=>{if(e.target.id==='roomMinutes'){const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>180){toast('1〜180分で入力してください');e.target.value=duration;return}setDuration(n);document.querySelectorAll('[data-room-duration]').forEach(b=>b.classList.remove('selected'));return}if(e.target.id==='roomTask'){state.focusTaskId=e.target.value;save()}if(e.target.id==='roomPlace'){state.roomPlace=e.target.value;save();render()}if(e.target.id==='roomMark'){state.roomMark=e.target.value.trim().slice(0,30);save()}if(e.target.dataset.task){const t=state.tasks.find(t=>t.id===Number(e.target.dataset.task));if(!t){render();return}completeTask(t,e.target.checked)}});
setInterval(()=>{if(pendingRender&&!typing()){pendingRender=false;render()}refreshDay();tickTimer();refreshRooms();refreshSky()},500);
initializePersistentData();
render();
tickTimer();
document.addEventListener('visibilitychange',()=>{if(!document.hidden){fetchWeather();requestWakeLock();refreshDay();tickTimer()}});
window.addEventListener?.('focus',()=>{refreshDay();tickTimer()});



function openProfileEditor(){const p=state.profile;modal(`<h2>プロフィールを編集</h2><form id="profileForm"><fieldset class="avatar-options"><legend>アイコン</legend>${[0,1,2,3].map(n=>`<label><input type="radio" name="avatar" value="${n}" ${p.avatar===n?'checked':''} aria-label="アイコン${n+1}"><span class="avatar sprite s${n}"></span></label>`).join('')}</fieldset><label>名前<input name="name" maxlength="30" required value="${esc(p.name)}"></label><label>大学<input name="university" maxlength="60" required value="${esc(p.university)}"></label><label>学部<select name="department">${['','総合政策学部','環境情報学部','看護医療学部'].map(d=>`<option value="${d}" ${p.department===d?'selected':''}>${d||'選ばない'}</option>`).join('')}${p.department&&!['総合政策学部','環境情報学部','看護医療学部'].includes(p.department)?`<option selected>${esc(p.department)}</option>`:''}</select></label><label>学年<select name="year">${['1年生','2年生','3年生','4年生','5年生','6年生','大学院生','その他'].map(y=>`<option ${y===p.year?'selected':''}>${y}</option>`).join('')}</select></label><p class="form-error" id="profileError" role="alert"></p><button class="primary icon-btn" aria-label="プロフィールを保存" title="保存">${icon('check')}</button></form>`);
$('#profileForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),university=f.get('university').trim(),avatar=Number(f.get('avatar'));if(!name||!university){$('#profileError').textContent='名前と大学を入力してください。';return}if(![0,1,2,3].includes(avatar))return;state.profile={name,university,department:f.get('department').trim(),year:f.get('year'),avatar};save();$('#modal').close();render();toast('プロフィールを保存しました')};}
function openSettings(){const st=state.settings,times=[...new Set([15,25,50,duration])].sort((a,b)=>a-b);modal(`<h2>設定</h2><form id="settingsForm"><p class="settings-group">終わりの合図</p><label class="switch-row"><span>振動</span><input type="checkbox" name="vibrate" ${st.vibrate?'checked':''}></label><label class="switch-row"><span>音<small>図書館などでは切っておくと安心</small></span><input type="checkbox" name="sound" ${st.sound?'checked':''}></label><label class="switch-row"><span>画面を閉じていても通知</span><input type="checkbox" name="notify" ${st.notify?'checked':''}></label><p class="settings-group">タスク</p><label class="switch-row"><span>完了したタスクを隠す</span><input type="checkbox" name="hideCompleted" ${st.hideCompleted?'checked':''}></label><button class="primary icon-btn" aria-label="設定を保存" title="保存">${icon('check')}</button></form><p class="settings-hint">データはこのスマホにだけ保存されます。</p><button class="textbtn settings-logout" data-logout>ログアウト</button>`);
$('#settingsForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);let notify=f.get('notify')==='on';if(notify&&'Notification' in window&&Notification.permission==='default'){try{await Notification.requestPermission()}catch{}}if(notify&&(!('Notification' in window)||Notification.permission!=='granted')){notify=false;toast('通知が許可されていません。端末の設定から変更できます')}else toast('設定を保存しました');state.settings={hideCompleted:f.get('hideCompleted')==='on',vibrate:f.get('vibrate')==='on',sound:f.get('sound')==='on',notify};save();$('#modal').close();render()};}

function completeTask(t,done){t.done=done;if(done)t.doneAt ||= Date.now();else delete t.doneAt;if(t.done&&!state.completedTaskIds.includes(t.id))state.completedTaskIds.push(t.id);if(t.done&&!t.rewarded){state.points+=20;t.rewarded=true;toast('ひとつ達成！ 田んぼに +20 pt','rice_stage_04')}save();render()}
function focusTaskId(){if(running&&sessionTask!==null)return String(sessionTask);if(state.focusTaskId==='')return '';const open=state.tasks.filter(t=>!t.done);return String((open.find(t=>String(t.id)===String(state.focusTaskId))||open[0])?.id??'')}
function openDeleteTask(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;modal(`<h2>タスクを削除しますか？</h2><p>${esc(task.title)}</p><div class="delete-actions"><button class="textbtn closemodal">やめる</button><button class="delete-confirm" data-confirm-delete-task="${id}">削除する</button></div>`)}
function deleteTask(id){if(!state.tasks.some(t=>t.id===id))return;state.tasks=state.tasks.filter(t=>t.id!==id);if(String(state.focusTaskId)===String(id))delete state.focusTaskId;save();$('#modal').close();render();toast('タスクを削除しました')}

function setDuration(n){duration=n;state.duration=n;if(!running){remaining=n*60;deadline=null;sessionId=null}save()}
function renderFriends(){if(friendView!=='rooms')friendView='people';const content=friendView==='people'?renderMap():renderRooms();
return head(friendView==='rooms'?'いっしょに集中しよう':'なかまとつながろう')+`<div class="friend-views">${[['rooms','作業場'],['people','仲間']].map(([v,l])=>`<button data-friend-view="${v}" aria-pressed="${friendView===v}" class="${friendView===v?'selected':''}">${l}</button>`).join('')}</div>`+content}
function openPerson(key){const p=people[key];if(!p)return;const connected=state.connections.includes(key);modal(`<div class="person-detail"><span class="avatar sprite s${p.avatar}"></span><h2>${esc(p.name)}</h2><p>${esc(p.department)} · ${esc(p.year)}</p><button class="primary meeting-join" data-connect="${key}" aria-pressed="${connected}">${connected?'仲間から外す':'仲間に追加する'}</button>${roomOf(key)&&!running?`<button class="textbtn" data-room="${roomOf(key).key}">作業場を見る</button>`:''}</div>`)}


function navIcon(name){if(name==='profile')return `<span class="nav-art nav-face avatar sprite s${state.profile.avatar}" aria-hidden="true"></span>`;const assets={home:'paddy_4_plots',tasks:'calendar',friends:'students_group_02'};return art(assets[name],'nav-art nav-'+name,'')}

function initializePersistentData(){
 let changed=false;
 restoreTimer();
 if(changed)save();
}
function restoreTimer(){const t=state.timer;if(t&&Number.isInteger(t.duration)&&t.duration>=1&&t.duration<=180){duration=t.duration;remaining=Number.isFinite(t.remaining)?Math.max(0,Math.min(t.remaining,duration*60)):duration*60;running=!!t.running&&Number.isFinite(t.deadline);deadline=running?t.deadline:null;sessionId=t.sessionId||null;sessionTask=t.sessionTask??null;if(running)remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000))}if(running&&!state.room)state.room={mine:true,host:'me',title:'自由に集中',type:'勉強',endAt:deadline,joinedAt:deadline-duration*60000,joinAt:deadline+1};if(!running)state.room=null}
// 別のタブで変更されたら、こちらの表示も最新にする
window.addEventListener?.('storage',e=>{if(e.key!=='tanboru-v1'||!e.newValue)return;try{state=JSON.parse(e.newValue)}catch{return}normalizeState();restoreTimer();render()});
function refreshDay(){const now=new Date(),next=iso(now);if(next===todayISO)return false;const previous=todayISO;today=now;todayISO=next;state.tasks.forEach(t=>{if(t.demo)t.date=next});save();if(selectedDate===previous){selectedDate=next;month=new Date(now.getFullYear(),now.getMonth(),1)}taskPage=0;render();return true}
function tickTimer(){if(!running)return;remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));if($('#time'))$('#time').textContent=timeText();if($('#quicktime'))$('#quicktime').textContent=timeText();if(remaining>0){roomTick();return}const doneAt=Date.now(),room=state.room,others=room?roomMembers(room):[],earned=room?Math.max(1,Math.round((room.endAt-room.joinedAt)/60000)):duration,bonus=others.length?10:0,task=state.tasks.find(t=>String(t.id)===String(sessionTask));running=false;deadline=null;remaining=duration*60;if(!sessionId||state.lastCompletedSession!==sessionId){state.points+=earned*2+bonus;if(others.length)state.togetherPoints+=earned*2+bonus;state.minutes+=earned;state.sessions++;state.lastCompletedSession=sessionId;if(task)task.focusMinutes=(task.focusMinutes||0)+earned;state.recentTogether=[...new Set([...others.map(o=>o[0]),...state.recentTogether])].slice(0,6);state.roomHistory=[{at:doneAt,place:room?.place||'',minutes:earned,task:task?.title||'',with:others.map(o=>o[0])},...state.roomHistory].slice(0,120)}sessionId=null;sessionTask=null;state.room=null;releaseWakeLock();save();render();alertDone(earned,task);const newFriends=others.map(o=>o[0]).filter(k=>!state.connections.includes(k));modal(`<h2>${others.length?`みんなで${earned}分、やりきった！`:`${earned}分間、おつかれさま！`}</h2>${others.length&&!newFriends.length?`<div class="done-faces">${['me',...others.map(o=>o[0])].map(k=>`<span class="avatar sprite s${k==='me'?state.profile.avatar:people[k].avatar}"></span>`).join('')}</div>`:`<img class="result-art asset-img" src="assets/library/focus_complete.webp" alt="集中完了">`}${task?`<p class="focus-result-task">${esc(task.title)}</p>`:''}<p class="done-points">+${earned*2+bonus} pt${bonus?'<span>いっしょに +10</span>':''}</p>${newFriends.length?`<div class="befriend-row">${newFriends.map(k=>`<button class="befriend" data-befriend="${k}" aria-label="${esc(people[k].name)}さんを仲間に追加"><span class="avatar sprite s${people[k].avatar}"></span><span class="befriend-badge">${icon('plus')}</span><small>${esc(people[k].name)}</small></button>`).join('')}</div>`:''}${photoButton(doneAt,task&&!task.done?task.id:'')}${task&&!task.done?`<button class="primary" data-complete-task="${task.id}">タスクを完了にする</button><button class="textbtn closemodal" data-page="home">あとで</button>`:'<button class="primary closemodal" data-page="home">田んぼへ戻る</button>'}`)}
// 集中終了の合図：画面を見ていなくても気づけるように、振動・音・端末通知を出す
function prepareAlerts(){if(!state.settings.sound)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume?.()}catch{}}
function chime(){if(!audioCtx)return;try{const t=audioCtx.currentTime;[784,988,1175].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0.0001,t+i*.18);g.gain.exponentialRampToValueAtTime(.25,t+i*.18+.02);g.gain.exponentialRampToValueAtTime(.0001,t+i*.18+.5);o.connect(g).connect(audioCtx.destination);o.start(t+i*.18);o.stop(t+i*.18+.55)})}catch{}}
function alertDone(earned,task){if(state.settings.vibrate)navigator.vibrate?.([200,120,200]);if(state.settings.sound)chime();if(state.settings.notify&&document.hidden&&'Notification' in window&&Notification.permission==='granted'){try{new Notification('たんぼる',{body:`${earned}分の集中が終わりました${task?'：'+task.title:''}`,icon:'assets/icons/icon-192.png'})}catch{}}}
// 集中中は画面が消えないようにする（対応ブラウザのみ）
async function requestWakeLock(){try{if(running&&!wakeLock&&navigator.wakeLock&&!document.hidden){wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null})}}catch{wakeLock=null}}
function releaseWakeLock(){wakeLock?.release?.().catch?.(()=>{});wakeLock=null}

// ===== 作業場 =====
const hhmm=t=>new Date(t).toTimeString().slice(0,5);
function roomNow(t,now=Date.now()){const c=t.cycle*60000,o=t.offset*60000,startAt=Math.floor((now-o)/c)*c+o,endAt=startAt+t.minutes*60000;return {...t,startAt,endAt,live:now<endAt,left:Math.ceil((endAt-now)/60000),nextAt:startAt+c}}
// 自分の作業場に入ってきた人は、元の作業場からいなくなる
function liveRooms(now=Date.now()){const guestBusy=state.room?.mine&&now>=state.room.joinAt,guestKey=state.room?.mine?roomGuest(state.room)[0]:null;const night=skyKind()==='night';return roomTemplates.filter(t=>!(guestBusy&&(t.host===guestKey||t.members.some(m=>m[0]===guestKey)))&&!(t.dayOnly&&night)&&!(t.nightOnly&&!night)).map(t=>roomNow(t,now))}
function placeIcon(p){return icon(p===ONLINE?'online':'pin')}
function roomJoinable(r){return r.live&&r.left>=3&&r.members.length<r.capacity}
// 自分の作業場には、ひらいた時点で来る人が決まっている（最初は「向かっています」）
function roomMembers(room){return room.mine?[roomGuest(room)]:room.members}
function roomName(room){return room.mine?'あなたの作業場':people[room.host].name+'の作業場'}
function faces(keys){return keys.map(k=>`<span class="avatar sprite s${k==='me'?state.profile.avatar:people[k].avatar}"></span>`).join('')}
function taskOptions(){const id=focusTaskId();return state.tasks.filter(t=>!t.done).map(t=>`<option value="${t.id}" ${id===String(t.id)?'selected':''}>${esc(t.title)}</option>`).join('')+`<option value="" ${id===''?'selected':''}>自由に集中する</option>`}
const stamps=['がんばろう','いいね','あと少し','おつかれ'];
const selectArrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';
function renderRooms(){
 if(running&&state.room){const r=state.room,others=roomMembers(r),task=state.tasks.find(t=>String(t.id)===String(sessionTask));
  const now=Date.now(),guestComing=r.mine&&now<r.arriveAt,meStatus=r.mine||r.arrived?'集中中':'向かっています';
  return `<section class="card room-live"><div class="between"><span class="room-live-head"><span class="pill">${esc(roomName(r))}</span><span class="room-place-line">${placeIcon(r.place)}${esc(r.place||'')}</span>${r.mark?`<span class="room-mark">目印：${esc(r.mark)}</span>`:''}</span><button class="textbtn icon-btn" data-leave-room aria-label="作業場を出る" title="作業場を出る">${icon('exit')}</button></div><div class="room-clock"><strong id="time">${timeText()}</strong><span>${esc(task?task.title:'自由に集中')}</span></div><ul class="room-members tiles"><li><span class="member-tile me"><span class="avatar sprite s${state.profile.avatar}"></span><b>あなた</b>${!r.mine&&!r.arrived?'<button class="arrived-pill" data-arrived aria-label="着いたことを知らせる">着いた</button>':''}</span></li>${others.map(([k,t])=>`<li><button class="member-tile" data-cheer="${k}" aria-label="${esc(people[k].name)}さん（${esc(t)}）に拍手を送る"><span class="avatar sprite s${people[k].avatar}"></span><b>${esc(people[k].name)}</b>${guestComing?`<small class="coming">${r.place===ONLINE?'もうすぐ':'向かっています'}</small>`:''}</button></li>`).join('')}</ul>${others.length?`<div class="room-stamps" aria-label="スタンプを送る">${stamps.map(t=>`<button data-stamp="${t}">${t}</button>`).join('')}</div>`:''}<div class="room-grow"><img id="roomRice" class="room-rice" src="${suppliedAssets[riceFor(r)]}" alt=""><small>集中するほど、稲がのびていく</small></div><p class="room-note">${others.length?'いっしょに終えると +10 pt ボーナス':'だれかが入ってくるのを待っています'}</p></section>`}
 const rooms=liveRooms().filter(roomJoinable);
 return `<section class="card room-create"><h2 class="sectiontitle">自分の作業場をひらく</h2><div class="room-select"><select id="roomTask" aria-label="取り組むタスク">${taskOptions()}</select>${selectArrow}</div><div class="room-select room-place">${placeIcon(state.roomPlace)}<select id="roomPlace" aria-label="集まる場所">${[...sfcPlaces,ONLINE].map(x=>`<option ${state.roomPlace===x?'selected':''}>${x}</option>`).join('')}</select>${selectArrow}</div>${state.roomPlace===ONLINE?'':`<input id="roomMark" class="room-mark-input" maxlength="30" value="${esc(state.roomMark||'')}" placeholder="目印（例：窓側の席・青いパーカー）" aria-label="相手に見つけてもらう目印">`}<div class="room-times">${[15,25,50].map(n=>`<button data-room-duration="${n}" class="${duration===n&&!customTime?'selected':''}">${n}分</button>`).join('')}${customTime||![15,25,50].includes(duration)?`<label class="room-custom selected"><input id="roomMinutes" type="number" min="1" max="180" step="1" value="${duration}" aria-label="集中する時間（分）"><span>分</span></label>`:'<button data-room-custom>その他</button>'}<button class="primary icon-btn" data-open-room aria-label="作業場をひらいて集中する" title="ひらいて集中する">${icon('play')}</button></div></section><p class="search-count">いま集中している作業場</p><div class="room-list">${rooms.length?'':`<div class="search-empty">いま集中している人はいません。<br>自分の作業場をひらいてみよう</div>`}${rooms.map(r=>`<button class="card room-row" data-room="${r.key}"><span class="room-faces">${faces(r.members.map(m=>m[0]))}</span><span class="room-copy"><b>${esc(people[r.host].name)}の作業場</b><small>${esc(r.place)}</small><small class="room-status">あと${r.left}分</small></span><span class="room-count">${r.members.length} / ${r.capacity}</span>${icon('right')}</button>`).join('')}</div>`}
function quickFocus(){const r=state.room;if(running&&r)return `<section class="card quickfocus" data-go-rooms role="button" tabindex="0" aria-label="作業場を開く"><div><h2><span id="quicktime">${timeText()}</span> ${esc(roomName(r))}で集中中</h2></div><button class="primary icon-btn" data-page="friends" data-friend-view="rooms" aria-label="作業場を開く" title="作業場を開く">${icon('focus')}</button></section>`;const live=[...new Set(liveRooms().filter(roomJoinable).flatMap(r=>r.members.map(m=>m[0])))];return `<section class="card quickfocus" data-go-rooms role="button" tabindex="0" aria-label="作業場を見る"><div><h2>みんなと集中する</h2>${live.length?`<span class="quick-faces">${faces(live.slice(0,4))}<small>${live.length}人が集中中</small></span>`:''}</div><button class="primary icon-btn" data-page="friends" data-friend-view="rooms" aria-label="作業場を見る" title="作業場">${icon('focus')}</button></section>`}
function openRoom(key){const t=roomTemplates.find(t=>t.key===key);if(!t)return;if(running){page='friends';friendView='rooms';render();toast('いまの作業場を出てから入れます');return}const r=liveRooms().find(x=>x.key===key);if(!r){toast(people[t.host].name+'さんはいま別の作業場にいます');return}if(!roomJoinable(r)){toast(people[t.host].name+'さんはいま集中していません');return}modal(`<div class="room-detail"><span class="pill">${esc(r.type)}</span><h2>${esc(people[r.host].name)}の作業場</h2><p class="room-place-line">${placeIcon(r.place)}${esc(r.place)}</p>${r.mark?`<p class="room-mark">目印：${esc(r.mark)}</p>`:''}<p class="room-time">${esc(r.title)} · あと${r.left}分</p><ul class="room-members">${r.members.map(([k,task])=>`<li><button data-person="${k}"><span class="avatar sprite s${people[k].avatar}"></span><span><b>${esc(people[k].name)}</b><small>${esc(task)}</small></span></button></li>`).join('')}</ul>${`<label class="room-label" for="joinTask">取り組むタスク</label><div class="room-select"><select id="joinTask">${taskOptions()}</select>${selectArrow}</div><button class="primary" data-join-room="${key}">${r.place===ONLINE?'オンラインで参加する':'ここで合流して集中する'}</button>`}</div>`)}
function joinRoom(key){const r=liveRooms().find(x=>x.key===key);if(!r||!roomJoinable(r)||running){$('#modal').close();render();toast('この作業場にはいま入れません');return}startSession({mine:false,key,host:r.host,title:r.title,type:r.type,place:r.place,mark:r.mark,endAt:r.endAt,members:r.members,arrived:r.place===ONLINE},$('#joinTask')?.value??focusTaskId());toast(people[r.host].name+'さんの作業場に入りました')}
function openOwnRoom(){if(running)return;const n=Number($('#roomMinutes')?.value||duration);if(!Number.isInteger(n)||n<1||n>180){toast('1〜180分で入力してください');return}setDuration(n);const taskId=$('#roomTask')?.value??focusTaskId(),task=state.tasks.find(t=>String(t.id)===String(taskId)),now=Date.now();const place=$('#roomPlace')?.value||state.roomPlace,online=place===ONLINE,mark=online?'':($('#roomMark')?.value??state.roomMark??'').trim().slice(0,30);state.roomPlace=place;state.roomMark=mark;startSession({mine:true,host:'me',title:task?task.title:'自由に集中',type:'勉強',place,mark,guest:pickGuest(place),endAt:now+n*60000,joinAt:now+1500,arriveAt:online?now+8000:now+25000},taskId);toast('作業場をひらきました')}
function startSession(room,taskId){const now=Date.now();state.room={...room,joinedAt:now};running=true;deadline=room.endAt;remaining=Math.ceil((deadline-now)/1000);sessionId='room-'+now+'-'+Math.random().toString(36).slice(2);sessionTask=String(taskId);if(taskId!=='')state.focusTaskId=String(taskId);prepareAlerts();requestWakeLock();save();if($('#modal').open)$('#modal').close();page='friends';friendView='rooms';render()}
function focusedMinutes(){return state.room?Math.max(0,Math.floor((Math.min(Date.now(),state.room.endAt)-state.room.joinedAt)/60000)):0}
// 途中で出たときは、それまでの分を半分のポイント（1分=1pt）にする
function leaveRoom(){const m=focusedMinutes(),room=state.room,others=room?roomMembers(room).map(o=>o[0]):[],task=state.tasks.find(t=>String(t.id)===String(sessionTask));if(m>=1){state.points+=m;state.minutes+=m;if(task)task.focusMinutes=(task.focusMinutes||0)+m;if(others.length){state.recentTogether=[...new Set([...others,...state.recentTogether])].slice(0,6);state.roomHistory=[{at:Date.now(),place:room.place||'',minutes:m,task:task?.title||'',with:others,left:true},...state.roomHistory].slice(0,120)}}running=false;deadline=null;remaining=duration*60;sessionId=null;sessionTask=null;state.room=null;releaseWakeLock();save();$('#modal').close();render();toast(m>=1?`作業場を出ました（+${m} pt）`:'作業場を出ました')}
// 集中中のできごと：自分の作業場に人が入ってくる・途中で拍手が届く
function roomTick(){const r=state.room;if(!r)return;const now=Date.now();if(r.mine&&!r.joinNotified&&now>=r.joinAt){r.joinNotified=true;save();toast(people[roomGuest(r)[0]].name+(r.place===ONLINE?'さんがオンラインで入りました':'さんが作業場に向かっています'),'rice_mascot_happy');if(page==='friends'&&friendView==='rooms')render()}if(r.mine&&r.place!==ONLINE&&r.joinNotified&&!r.arriveNotified&&now>=r.arriveAt){r.arriveNotified=true;save();toast(people[roomGuest(r)[0]].name+'さんが着きました。目印で見つけてもらえました','rice_mascot_happy');if(page==='friends'&&friendView==='rooms'&&!$('#modal').open)render()}const others=roomMembers(r);if(!r.cheered&&others.length&&now>=r.joinedAt+(r.endAt-r.joinedAt)/2){r.cheered=true;save();toast(people[others[0][0]].name+'さんから「'+(Math.random()<.5?'いいね':'がんばろう')+'」','rice_mascot_happy')}const rice=$('#roomRice'),src=suppliedAssets[riceFor(r)];if(rice&&!rice.src.endsWith(src))rice.src=src}
function riceFor(r){const p=Math.max(0,Math.min(1,(Date.now()-r.joinedAt)/Math.max(1,r.endAt-r.joinedAt)));return 'rice_stage_0'+Math.min(6,1+Math.floor(p*6))}
function refreshRooms(){if(running||page!=='friends'&&page!=='home')return;const key=liveRooms().map(r=>r.key+r.live+r.left).join('|');if(key===roomsKey)return;roomsKey=key;if(!$('#modal').open&&!typing()&&(page==='home'||friendView==='rooms'))render()}

// ===== 天気と時間帯でホームの空を変える（SFC の現在の天気：Open-Meteo、登録不要） =====
const SFC_WEATHER_URL='https://api.open-meteo.com/v1/forecast?latitude=35.3881&longitude=139.4272&current=weather_code,is_day,temperature_2m&timezone=Asia%2FTokyo';
let skyShown='';
function freshWeather(){const w=state.weather;return w&&Date.now()-w.at<3*3600000?w:null}
function isWet(c){return (c>=51&&c<=67)||(c>=71&&c<=86)||c>=95}
function weatherLabel(c){return c<=1?'晴れ':c<=3?'くもり':c<=48?'霧':c<=57?'霧雨':c<=67?'雨':c<=77?'雪':c<=82?'にわか雨':c<=86?'雪':'雷雨'}
// 夜を優先（暗い時間は夜空）、昼は雨・雪なら雨の空、それ以外は晴れの空。天気が取れないときは時刻だけで判断
function skyKind(){const w=freshWeather(),h=new Date().getHours();if(w?!w.isDay:(h<6||h>=18))return 'night';return w&&isWet(w.code)?'rain':'clear'}
async function fetchWeather(){if(state.weather&&Date.now()-state.weather.at<30*60000)return;try{const res=await fetch(SFC_WEATHER_URL);if(!res.ok)return;const c=(await res.json()).current;if(!c||!Number.isFinite(c.weather_code))return;state.weather={at:Date.now(),code:c.weather_code,isDay:c.is_day===1,temp:Math.round(c.temperature_2m)};save();refreshSky(true)}catch{}}
function refreshSky(force){const k=skyKind()+(freshWeather()?.code??'');if(!force&&k===skyShown)return;const first=!skyShown;skyShown=k;if(!first&&page==='home'&&!$('#modal').open&&!typing())render();else document.body.dataset.sky=skyKind();if(Date.now()-(state.weather?.at||0)>=30*60000)fetchWeather()}
fetchWeather();

// ===== 田んぼにときどき来る生きもの（カラス・イナゴ）。タップすると逃げていく =====
let visitorTimer=null,visitorBusy=false;
const vimg=n=>'assets/library/'+n+'.webp',pause=ms=>new Promise(r=>setTimeout(r,ms));
const glide=(el,frames,ms)=>el.animate(frames,{duration:ms,easing:'ease-in-out',fill:'forwards'}).finished.catch(()=>{});
function scheduleVisitor(first){clearTimeout(visitorTimer);visitorTimer=setTimeout(()=>{if(page==='home'&&!document.hidden&&!$('#modal').open&&!visitorBusy&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)spawnVisitor();scheduleVisitor(false)},first?8000+Math.random()*7000:60000+Math.random()*60000)}
function spawnVisitor(kind){const field=$('.supplied-field');if(!field||visitorBusy)return;kind ||= skyKind()==='night'||Math.random()<.4?'grasshopper':'crow';visitorBusy=true;const el=document.createElement('img');el.className='visitor visitor-'+kind;el.alt='';el.draggable=false;field.appendChild(el);(kind==='crow'?crowVisit(el):grasshopperVisit(el)).finally(()=>{el.remove();visitorBusy=false})}
async function crowVisit(el){let leaving=false;el.onclick=()=>{leaving=true};const flap=()=>setInterval(()=>{el.src=vimg(el.src.includes('crow_fly1')?'crow_fly2':'crow_fly1')},180),land={x:42+Math.random()*22,y:44+Math.random()*8};
 el.src=vimg('crow_fly1');let f=flap();await glide(el,[{left:'-25%',top:'6%'},{left:land.x+'%',top:land.y+'%'}],2400);clearInterval(f);if(!el.isConnected)return;
 el.src=vimg('crow_land');await pause(450);
 for(let i=0;i<9&&!leaving&&el.isConnected;i++){el.src=vimg(i%2?'crow_land':'crow_peck');await pause(450)}
 if(!el.isConnected)return;if(leaving)toast('カラスを追いはらいました');
 el.src=vimg('crow_fly1');f=flap();await glide(el,[{left:land.x+'%',top:land.y+'%'},{left:'125%',top:'-15%'}],leaving?1000:1900);clearInterval(f)}
async function grasshopperVisit(el){let leaving=false;el.onclick=()=>{leaving=true};const ground=58+Math.random()*6,target=24+Math.random()*30;let x=-15;
 const hop=async(to,ms)=>{el.src=vimg('grasshopper_jump');await glide(el,[{left:x+'%',top:ground+'%'},{left:(x+to)/2+'%',top:(ground-9)+'%'},{left:to+'%',top:ground+'%'}],ms);x=to;if(el.isConnected)el.src=vimg('grasshopper_stand')};
 el.style.left=x+'%';el.style.top=ground+'%';el.src=vimg('grasshopper_stand');
 while(x<target-1&&el.isConnected){await hop(Math.min(target,x+18),650);await pause(350)}
 for(let i=0;i<12&&!leaving&&el.isConnected;i++)await pause(400);
 if(!el.isConnected)return;if(leaving)toast('イナゴがぴょんと逃げていきました');
 while(x<115&&el.isConnected){await hop(x+22,leaving?420:650);await pause(leaving?60:250)}}
scheduleVisitor(true);

// ===== つながりマップ：真ん中の「あなた」から、いっしょに集中した人へ水路がのびる。回数が多いほど水路が太い =====
// 人数に合わせて「あなた」のまわりへ均等に並べる（上から時計回り）
const mapSlot=(i,n)=>{const a=-Math.PI/2+(n===2?Math.PI/2:0)+i*2*Math.PI/n;return [50+Math.cos(a)*37,50+Math.sin(a)*34]},MAP_MAX=6;
function togetherStats(){const st={};state.roomHistory.forEach(h=>h.with.forEach(k=>{st[k] ||= {count:0,minutes:0};st[k].count++;st[k].minutes+=h.minutes}));return st}
function roomOf(k){const live=liveRooms().filter(roomJoinable);return live.find(t=>t.host===k)||live.find(t=>t.members.some(m=>m[0]===k))}
function renderMap(){
 const st=togetherStats(),all=[...new Set([...state.connections,...Object.keys(st),...state.recentTogether])].filter(k=>people[k]).sort((a,b)=>(st[b]?.count||0)-(st[a]?.count||0)),keys=all.slice(0,all.length>MAP_MAX?MAP_MAX-1:MAP_MAX),rest=all.slice(keys.length);
 if(!keys.includes(mapSelected))mapSelected=keys[0]||null;
 const C=[50,50],stream=(k,[x,y],i)=>{const friend=state.connections.includes(k),n=st[k]?.count||0;return friend?`<img class="map-stream-img curve" src="assets/library/stream_curve.webp" data-x="${x}" data-y="${y}" data-k="${.7+Math.min(4,n)*.15}" data-flip="${i%2}" alt="">`:`<img class="map-stream-img straight" src="assets/library/stream_straight.webp" data-x="${x}" data-y="${y}" alt="">`};
 const slots=keys.length+(rest.length?1:0);const nodes=keys.map((k,i)=>{const [x,y]=mapSlot(i,slots),p=people[k],n=st[k]?.count||0,friend=state.connections.includes(k);return `<button class="map-node ${friend?'':'pending'} ${mapSelected===k?'selected':''}" style="left:${x}%;top:${y}%" data-map-person="${k}" aria-label="${esc(p.name)}${n?'、いっしょに'+n+'回':''}${friend?'':'（まだ仲間ではありません）'}"><span class="map-blob"><span class="avatar sprite s${p.avatar}"></span>${n?`<span class="map-count">${n}回</span>`:''}</span><b>${esc(p.name)}</b></button>`}).join('');
 const deco=keys.map((k,i)=>{const [x,y]=mapSlot(i,slots),mx=(x+C[0])/2,my=(y+C[1])/2;return i%2?'':`<img class="map-sprig" src="assets/library/map_grass.webp" alt="" data-x="${x}" data-y="${y}" data-side="${i%4?-1:1}">`}).join('');
 const sel=mapSelected&&people[mapSelected],s0=sel&&st[mapSelected],friend=sel&&state.connections.includes(mapSelected),room=sel&&roomOf(mapSelected);
 const detail=sel?`<section class="card map-detail"><span class="avatar sprite s${sel.avatar}"></span><button class="map-detail-copy" data-map-history="${mapSelected}" aria-label="${esc(sel.name)}さん（${esc(sel.year)}）との記録を見る"><b>${esc(sel.name)}<span class="map-year">${esc(sel.year)}</span></b><small>${s0?`一緒に${s0.count}回・${s0.minutes}分`:`${esc(sel.department)} · ${esc(sel.year)}`} ›</small></button>${friend?(room&&!running?`<span class="map-now live">いま集中中</span><button class="primary" data-room="${room.key}">一緒に集中</button>`:`<span class="map-now">${running?'あなたが集中中':'いまは休憩中'}</span>`):`<button class="primary icon-btn map-add" data-connect="${mapSelected}" aria-label="${esc(sel.name)}さんを仲間に追加" title="仲間に追加">${icon('plus')}</button>`}</section>`:'';
 return `<section class="card map-card"><div class="map-head"><div><h2>つながりマップ</h2><p>${keys.length?`いっしょに集中した仲間 ${state.connections.length}人`:'作業場でいっしょに集中すると、ここに水路がのびていきます'}</p></div><span class="map-total">${icon('friends')}${state.connections.length}</span></div><div class="map-area"><div class="map-streams" aria-hidden="true">${keys.map((k,i)=>stream(k,mapSlot(i,slots),i)).join('')}${keys.length?'':'<img class="map-empty-art" src="assets/library/stream_branch.webp" alt="">'}</div>${deco}<button class="map-node me" style="left:50%;top:50%" data-page="profile" aria-label="マイページを開く"><span class="map-blob"><span class="avatar sprite s${state.profile.avatar}"></span></span><b>あなた</b></button>${nodes}${rest.length?(()=>{const [x,y]=mapSlot(keys.length,slots);return `<button class="map-node more" style="left:${x}%;top:${y}%" data-map-more aria-label="ほか${rest.length}人を見る"><span class="map-blob">+${rest.length}</span><b>ほか${rest.length}人</b></button>`})():''}</div>${keys.length?'':'<button class="primary map-empty-btn" data-friend-view="rooms">作業場をさがす</button>'}</section>${detail}`}
// 人ごとの「いっしょに集中した記録」（つながりマップで人を押したとき）
function openTogetherHistory(k){const p=people[k];if(!p)return;const list=state.roomHistory.filter(h=>h.with.includes(k));modal(`<div class="together-history"><span class="avatar sprite s${p.avatar}"></span><h2>${esc(p.name)}さんとの記録</h2><p class="settings-hint">${esc(p.department)} · ${esc(p.year)}</p>${list.length?`<ul>${list.map(h=>`<li><div class="history-top"><b>${new Date(h.at).toLocaleDateString('ja-JP',{month:'numeric',day:'numeric',weekday:'short'})} ${hhmm(h.at)}</b><span>${h.minutes}分${h.left?'（途中まで）':''}</span></div><p class="room-place-line">${placeIcon(h.place)}${esc(h.place||'')}</p><small>${esc(h.task||'自由に集中')}</small></li>`).join('')}</ul>`:'<p>まだいっしょに集中した記録はありません。</p>'}${state.connections.includes(k)?'':`<button class="primary icon-btn map-add" data-connect="${k}" aria-label="${esc(p.name)}さんを仲間に追加" title="仲間に追加">${icon('plus')}</button>`}</div>`)}
// ポップアップの外側を押したら閉じる
$('#modal').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('[data-go-rooms]')){e.preventDefault();page='friends';friendView='rooms';render()}});
// マップに入りきらない人の一覧
function openMapList(){const st=togetherStats(),all=[...new Set([...state.connections,...Object.keys(st),...state.recentTogether])].filter(k=>people[k]).sort((a,b)=>(st[b]?.count||0)-(st[a]?.count||0));modal(`<div class="together-history"><h2>つながっている人</h2><ul>${all.map(k=>`<li><button class="map-list-row" data-map-person="${k}" data-close-modal><span class="avatar sprite s${people[k].avatar}"></span><span><b>${esc(people[k].name)}<span class="map-year">${esc(people[k].year)}</span></b><small>${st[k]?`一緒に${st[k].count}回・${st[k].minutes}分`:esc(people[k].department)}</small></span></button></li>`).join('')}</ul></div>`)}
// 水路のイラストを「あなた」から相手まで、向きと長さを合わせて置く（曲がった水路は回数が多いほど太く）
function layoutMap(){const area=$('.map-area');if(!area)return;const W=area.clientWidth,H=area.clientHeight,cx=W/2,cy=H/2;area.querySelectorAll('.map-sprig').forEach(g=>{const x=g.dataset.x/100*W,y=g.dataset.y/100*H,dx=x-cx,dy=y-cy,L=Math.hypot(dx,dy)||1,side=Number(g.dataset.side);g.style.left=`${cx+dx*.55-dy/L*16*side}px`;g.style.top=`${cy+dy*.55+dx/L*16*side}px`});area.querySelectorAll('.map-stream-img').forEach(img=>{const x=img.dataset.x/100*W,y=img.dataset.y/100*H,dx=x-cx,dy=y-cy,L=Math.hypot(dx,dy),th=Math.atan2(dy,dx)*180/Math.PI,mx=(cx+x)/2,my=(cy+y)/2;if(img.classList.contains('curve')){const NW=520,NH=485,chord=Math.hypot(.86*NW,.847*NH),sc=L/chord,f=img.dataset.flip==='1'?-1:1;img.style.cssText=`width:${NW}px;height:${NH}px;left:${mx-NW/2}px;top:${my-NH/2}px;transform:rotate(${th}deg) scale(${sc},${f*sc*Number(img.dataset.k)}) rotate(42.6deg)`}else img.style.cssText=`width:${L}px;height:9px;left:${mx-L/2}px;top:${my-4.5}px;transform:rotate(${th}deg)`})}
// ===== ログイン（ダミーのIDとパスワードが入っていて、押せばそのまま入れる） =====
// はじめる画面（ロゴ・キャッチコピー・はじめる・ログイン）
function welcomeView(){return `<section class="welcome"><img class="welcome-logo" src="assets/library/login_logo.webp" alt="たんぼる"><p class="welcome-catch">だれかといっしょに、<br>今日の一歩。</p><div class="welcome-actions"><button class="welcome-start" data-start>はじめる</button><p class="welcome-login">アカウントをお持ちの方は <button class="welcome-login-link" data-login-form>ログイン</button></p></div></section>`}
function enterApp(){state.loggedIn=true;loginStep='welcome';save();page='home';render();toast(`ようこそ、${state.profile.name}さん`,'rice_mascot_happy')}
function loginView(){return `<section class="login"><button class="textbtn icon-btn login-back" data-login-back aria-label="もどる">${icon('left')}</button><img class="login-logo" src="assets/library/login_logo.webp" alt="たんぼる"><form id="loginForm" class="login-card" method="post" action="#" novalidate><label>ID<input name="loginId" autocomplete="username" value="tanaka.haku"></label><label>パスワード<input name="loginPw" type="password" autocomplete="current-password" value="tanboru2026"></label><p class="form-error" id="loginError" role="alert"></p><button class="primary login-btn">ログイン</button></form></section>`}
document.addEventListener('submit',e=>{if(!e.target.matches?.('#loginForm'))return;e.preventDefault();const f=new FormData(e.target);if(!String(f.get('loginId')||'').trim()||!String(f.get('loginPw')||'')){$('#loginError').textContent='IDとパスワードを入力してください。';return}enterApp()});

// ===== 成果の写真（スマホの中に保存：画像は IndexedDB、一覧は state.photos） =====
const photoDB=(()=>{let ready;const open=()=>ready ||= new Promise((res,rej)=>{const q=indexedDB.open('tanboru-photos',1);q.onupgradeneeded=()=>q.result.createObjectStore('photos');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});const run=async(mode,fn)=>{const db=await open();return new Promise((res,rej)=>{const t=db.transaction('photos',mode),q=fn(t.objectStore('photos'));t.oncomplete=()=>res(q?.result);t.onerror=()=>rej(t.error)})};return{put:(id,blob)=>run('readwrite',st=>st.put(blob,id)),get:id=>run('readonly',st=>st.get(id)),del:id=>run('readwrite',st=>st.delete(id))}})();
const photoURLs=new Map();
// 撮った写真をたんぼるのカメラ枠に収めて、1枚のJPEG（900×1200）にする。窓はカメラ枠.png の透明部分（80,190)-(1006,1175)/1086×1448
const FRAME={src:'assets/library/camera_frame.webp',w:1086,h:1448,win:[80,190,1006,1175],r:62};let frameImg;
const loadImg=src=>new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src});
// 写真（画像や動画の1コマ）を枠の窓に合わせて切り抜き、枠を重ねて 900×1200 の JPEG にする。crop は元画像のどの範囲を窓に入れるか
async function composeWithFrame(src,sw,sh,crop,mirror){const frame=await (frameImg ||= loadImg(FRAME.src));const W=900,k=W/FRAME.w,H=Math.round(FRAME.h*k),c=document.createElement('canvas');c.width=W;c.height=H;const g=c.getContext('2d');g.fillStyle='#fffef8';g.fillRect(0,0,W,H);const [x0,y0,x1,y1]=FRAME.win.map(v=>v*k),ww=x1-x0,wh=y1-y0;if(!crop){const sc=Math.max(ww/sw,wh/sh),dw=sw*sc,dh=sh*sc;crop={sx:(sw-ww/sc)/2,sy:(sh-wh/sc)/2,sw:ww/sc,sh:wh/sc}}g.save();g.beginPath();g.roundRect?g.roundRect(x0,y0,ww,wh,FRAME.r*k):g.rect(x0,y0,ww,wh);g.clip();if(mirror){g.translate(x0+ww,0);g.scale(-1,1);g.drawImage(src,crop.sx,crop.sy,crop.sw,crop.sh,0,y0,ww,wh)}else g.drawImage(src,crop.sx,crop.sy,crop.sw,crop.sh,x0,y0,ww,wh);g.restore();g.drawImage(frame,0,0,W,H);return await new Promise(res=>c.toBlob(res,'image/jpeg',.85))}
async function shrinkPhoto(file){const url=URL.createObjectURL(file);try{const img=await loadImg(url);return await composeWithFrame(img,img.naturalWidth,img.naturalHeight)}finally{URL.revokeObjectURL(url)}}
async function savePhoto(file,opts){return savePhotoBlob(await shrinkPhoto(file),opts)}
async function savePhotoBlob(blob,{date,session}){if(!blob)throw new Error('compose');const id='p'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);await photoDB.put(id,blob);state.photos.unshift({id,date,at:Date.now(),session:session||null});save();return id}
async function hydratePhotos(root){for(const img of root.querySelectorAll('img[data-photo-id]')){const id=img.dataset.photoId;try{if(!photoURLs.has(id)){const blob=await photoDB.get(id);if(!blob){img.closest('.photo-cell')?.classList.add('missing');continue}photoURLs.set(id,URL.createObjectURL(blob))}img.src=photoURLs.get(id)}catch{img.closest('.photo-cell')?.classList.add('missing')}}}
function photoButton(at,taskId=''){return `<button class="photo-btn" data-camera-session="${at}" data-camera-task="${taskId}">${icon('camera')}<span>写真を残す</span></button>`}
document.addEventListener('change',async e=>{const inp=e.target;if(!inp.matches?.('input[data-cam-file]')||!inp.files?.[0])return;const file=inp.files[0];inp.value='';try{cam.blob=await shrinkPhoto(file);showShot()}catch{toast('この写真は使えませんでした')}});
function openPhoto(id){const p=state.photos.find(p=>p.id===id);if(!p)return;modal(`<div class="photo-view"><img data-photo-id="${id}" alt="成果の写真"><p class="settings-hint">${p.date.slice(5).replace('-','月')}日 ${hhmm(p.at)}</p><div class="delete-actions"><button class="textbtn" data-day-record="${p.date}">もどる</button><button class="delete-confirm" data-photo-delete="${id}">削除する</button></div></div>`);hydratePhotos($('#modalcontent'))}
async function deletePhoto(id){const p=state.photos.find(p=>p.id===id);try{await photoDB.del(id)}catch{}const u=photoURLs.get(id);if(u){URL.revokeObjectURL(u);photoURLs.delete(id)}state.photos=state.photos.filter(x=>x.id!==id);save();toast('写真を削除しました');if(p)openDayRecord(p.date);if(page==='tasks')render()}

// ===== その日のがんばり（カレンダーの日付から） =====
function dayRecord(date){const sessions=state.roomHistory.filter(h=>iso(new Date(h.at))===date).sort((a,b)=>a.at-b.at),tasks=state.tasks.filter(t=>t.done&&t.doneAt&&iso(new Date(t.doneAt))===date),photos=(state.photos||[]).filter(p=>p.date===date),minutes=sessions.reduce((n,h)=>n+h.minutes,0);return {sessions,tasks,photos,minutes,any:!!(sessions.length||tasks.length||photos.length)}}
function dayRecordButton(date){const r=dayRecord(date);if(!r.any)return date<=todayISO?`<button class="day-record-btn empty" data-day-record="${date}">${icon('camera')}<span>この日のがんばりを残す</span>${icon('right')}</button>`:'';return `<button class="day-record-btn" data-day-record="${date}">${art('rice_bundle','day-record-art','')}<span>がんばり　${[r.minutes?`集中${r.minutes}分`:'',r.tasks.length?`完了${r.tasks.length}件`:'',r.photos.length?`写真${r.photos.length}枚`:''].filter(Boolean).join('・')}</span>${icon('right')}</button>`}
function openDayRecord(date){const r=dayRecord(date),[,mo,d]=date.split('-').map(Number);modal(`<div class="day-record"><h2>${mo}月${d}日のがんばり</h2><div class="day-sum"><span><b>${r.minutes}</b>分 集中</span><span><b>${r.tasks.length}</b>件 完了</span><span><b>${r.photos.length}</b>枚 写真</span></div>${r.sessions.length?`<h3>集中した記録</h3><ul class="day-list">${r.sessions.map(h=>`<li><div class="history-top"><b>${hhmm(h.at)}</b><span>${h.minutes}分${h.left?'（途中まで）':''}</span></div><p class="room-place-line">${placeIcon(h.place)}${esc(h.place||'')}</p><small>${esc(h.task||'自由に集中')}</small>${h.with.length?`<span class="day-faces">${faces(h.with)}<small>${h.with.map(k=>esc(people[k]?.name||'')).join('・')}さんと</small></span>`:''}</li>`).join('')}</ul>`:''}${r.tasks.length?`<h3>完了したタスク</h3><ul class="day-list tasks">${r.tasks.map(t=>`<li>${icon('check')}<span>${esc(t.title)}</span></li>`).join('')}</ul>`:''}<h3>写真</h3><div class="photo-grid">${r.photos.map(p=>`<button class="photo-cell" data-photo-view="${p.id}" aria-label="写真を大きく見る"><img data-photo-id="${p.id}" alt="成果の写真"></button>`).join('')}${date<=todayISO?`<button class="photo-cell add" data-camera-day="${date}" aria-label="写真を追加">${icon('camera')}</button>`:''}</div>${r.any?'':'<p class="settings-hint">この日の記録はまだありません。</p>'}</div>`);hydratePhotos($('#modalcontent'))}

// ===== 使い方（マイページから） =====
function openGuide(){const steps=[['rice_stage_03','タスクを植える','登録して、終えたらチェック。ひとつ +20pt で稲がのびる'],['students_study_02','作業場で集中','自分の作業場をひらく or 誰かの作業場に入る。やりきると 分数×2pt、いっしょなら +10pt'],['students_group_02','なかまとつながる','いっしょに集中した人と水路でつながる。回数が多いほど太くなる'],['rice_bundle','実りをあつめる','300pt で収穫、お米で図鑑の料理がふえる。写真はカレンダーから見返せる']];modal(`<div class="guide"><h2>たんぼるの使い方</h2><ol class="guide-steps">${steps.map(([a,t,d],i)=>`<li>${art(a,'guide-art','')}<div><b><span class="guide-no">${i+1}</span>${t}</b><p>${d}</p></div></li>`).join('')}</ol><button class="primary closemodal">わかった</button></div>`)}

// ===== アプリ内カメラ：映像の上にたんぼるの枠を重ね、枠の中をそのまま保存する =====
const cam={stream:null,facing:'environment',opts:null,blob:null};
function stopCamera(){cam.stream?.getTracks().forEach(t=>t.stop());cam.stream=null}
$('#modal').addEventListener('close',stopCamera);
async function openCamera(opts){cam.opts=opts;cam.blob=null;modal(`<div class="camera"><div class="camera-stage" id="camStage"><video id="camVideo" autoplay playsinline muted></video><img class="camera-frame" src="${FRAME.src}" alt=""></div><p class="camera-hint" id="camHint">枠の中に、今日の成果を</p><div class="camera-actions"><label class="textbtn camera-pick">写真から選ぶ<input type="file" accept="image/*" data-cam-file hidden></label><button class="camera-shutter" id="camShutter" aria-label="撮る"><span></span></button><button class="textbtn icon-btn" id="camFlip" aria-label="カメラを切り替える" title="切り替え">${icon('reset')}</button></div></div>`);await startCamera()}
async function startCamera(){stopCamera();const v=$('#camVideo');if(!v)return;if(!navigator.mediaDevices?.getUserMedia){noCamera('このブラウザではカメラを使えません');return}try{cam.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:cam.facing},width:{ideal:1280},height:{ideal:1280}},audio:false});v.srcObject=cam.stream;v.classList.toggle('mirror',cam.facing==='user');await v.play().catch(()=>{})}catch{noCamera('カメラを使えないので、写真から選んでください')}}
function noCamera(msg){const h=$('#camHint');if(h)h.textContent=msg;$('#camShutter')?.setAttribute('disabled','');$('#camFlip')?.setAttribute('disabled','');$('#camStage')?.classList.add('off')}
async function flipCamera(){cam.facing=cam.facing==='user'?'environment':'user';await startCamera()}
// 画面で枠の窓に見えていた範囲を、そのまま切り抜く
async function takeShot(){const v=$('#camVideo'),st=$('#camStage');if(!v||!v.videoWidth||!cam.stream)return;const sw=st.clientWidth,sh=st.clientHeight,vw=v.videoWidth,vh=v.videoHeight,sc=Math.max(sw/vw,sh/vh),ox=(sw-vw*sc)/2,oy=(sh-vh*sc)/2,k=sw/FRAME.w,[wx0,wy0,wx1,wy1]=FRAME.win.map(n=>n*k);const crop={sx:(wx0-ox)/sc,sy:(wy0-oy)/sc,sw:(wx1-wx0)/sc,sh:(wy1-wy0)/sc};$('#camShutter')?.setAttribute('disabled','');try{cam.blob=await composeWithFrame(v,vw,vh,crop,cam.facing==='user');showShot()}catch{toast('撮影できませんでした');$('#camShutter')?.removeAttribute('disabled')}}
function showShot(){stopCamera();const url=URL.createObjectURL(cam.blob);modal(`<div class="camera"><div class="camera-stage"><img class="camera-shot" src="${url}" alt="撮った写真"></div><div class="camera-actions review"><button class="textbtn" id="camRetake">撮り直す</button><button class="primary" id="camSave">この写真を残す</button></div></div>`)}
async function saveShot(){const o=cam.opts;if(!cam.blob||!o)return;const date=o.date||iso(new Date(o.session||Date.now()));$('#camSave')?.setAttribute('disabled','');try{const id=await savePhotoBlob(cam.blob,{date,session:o.session});toast('写真を残しました','rice_mascot_happy');if(page==='tasks')render();if(o.date)openDayRecord(date);else{const t=state.tasks.find(t=>String(t.id)===String(o.task));modal(`<div class="photo-done"><img data-photo-id="${id}" alt="成果の写真"><p>写真を残しました</p>${t&&!t.done?`<button class="primary" data-complete-task="${t.id}">タスクを完了にする</button><button class="textbtn closemodal" data-page="home">あとで</button>`:'<button class="primary closemodal" data-page="home">田んぼへ戻る</button>'}</div>`);hydratePhotos($('#modalcontent'))}}catch{toast('写真を保存できませんでした');$('#camSave')?.removeAttribute('disabled')}}
